import { execFileSync } from 'node:child_process';
import { existsSync, mkdtempSync, readFileSync, rmSync } from 'node:fs';
import { tmpdir } from 'node:os';
import { join } from 'node:path';

import { describe, expect, it } from 'vitest';

/**
 * RC-09A ownership-matrix counter-tests. The changed-path ownership matrix
 * (artifacts/agent-engineering-acceptance/runtime-authority-convergence-final/
 * changed-path-ownership.json) is generated by scripts/generate-rc09-ownership-matrix.mjs
 * from the EXACT cumulative candidate diff (accepted base -> RC-09 candidate):
 * every path maps to EXACTLY ONE owning RC package (RC-00..RC-08B); duplicates,
 * missing owners, or non-RC first-touch commits fail closed.
 *
 * The generator must be re-run whenever the accepted base or the RC-09
 * candidate HEAD changes; the committed matrix is the deterministic evidence.
 */
const REPO_ROOT = process.cwd();
const MATRIX_RELATIVE = 'artifacts/agent-engineering-acceptance/runtime-authority-convergence-final/changed-path-ownership.json';
const MATRIX_PATH = join(REPO_ROOT, ...MATRIX_RELATIVE.split('/'));
const GENERATOR_RELATIVE = 'scripts/generate-rc09-ownership-matrix.mjs';

function git(args: string[]): string {
  return execFileSync('git', args, { cwd: REPO_ROOT, encoding: 'utf8', maxBuffer: 1024 * 1024 * 64 }).trim();
}

function readMatrix(): {
  schema: string;
  generatedAt?: string;
  baseSha: string;
  headSha: string;
  totalPaths: number;
  byRc: Record<string, number>;
  entries: Array<{ path: string; rc: string; commit: string | null; preChain?: boolean }>;
} {
  return JSON.parse(readFileSync(MATRIX_PATH, 'utf8'));
}

describe('RC-09 changed-path ownership matrix', () => {
  it('exists, uses the correct schema, and matches the accepted base SHA', () => {
    expect(existsSync(MATRIX_PATH)).toBe(true);
    const matrix = readMatrix();
    expect(matrix.schema).toBe('runtime-authority-convergence-rc09-ownership/v1');
    expect(matrix.baseSha).toMatch(/^[a-f0-9]{40}$/);
    expect(matrix.headSha).toMatch(/^[a-f0-9]{40}$/);
  });

  it('covers the exact cumulative diff with exactly one RC owner per path', () => {
    const matrix = readMatrix();
    const actualDiff = git(['diff', '--name-only', `${matrix.baseSha}..${matrix.headSha}`])
      .split('\n')
      .filter(Boolean)
      .sort();
    const matrixPaths = matrix.entries.map((entry) => entry.path).sort();
    // The matrix is generated from the exact candidate diff — same set.
    expect(matrixPaths).toEqual(actualDiff);
    // Every path maps to exactly one RC; no duplicates, no missing owners.
    expect(new Set(matrixPaths).size).toBe(matrixPaths.length);
    for (const entry of matrix.entries) {
      expect(entry.rc).toMatch(/^RC-(0[0-8]|0[0-8][A-D]|0[0-8]R)$/);
    }
    // Sum of per-RC counts equals the total path count.
    const sum = Object.values(matrix.byRc).reduce((acc, count) => acc + count, 0);
    expect(sum).toBe(matrix.totalPaths);
  });

  it('the generator reproduces the committed matrix byte-for-byte', () => {
    const base = readMatrix().baseSha;
    const head = readMatrix().headSha;
    const regenerated = mkdtempSync(join(tmpdir(), 'rc09-matrix-'));
    const outputPath = join(regenerated, 'changed-path-ownership.json');
    try {
      execFileSync('node', [
        join(REPO_ROOT, GENERATOR_RELATIVE),
        '--base', base,
        '--head', head,
        '--output', outputPath,
      ], { cwd: REPO_ROOT, encoding: 'utf8', maxBuffer: 1024 * 1024 * 64 });

      // `generatedAt` is by construction the moment of generation, so it is the
      // only field allowed to differ. Everything else — path set, RC owners,
      // owning commits, ordering — must reproduce exactly, otherwise the
      // committed matrix is not evidence of anything.
      const { generatedAt: _committedAt, ...committed } = readMatrix();
      const { generatedAt: _regeneratedAt, ...fresh } = JSON.parse(readFileSync(outputPath, 'utf8'));
      expect(fresh).toEqual(committed);
    } finally {
      rmSync(regenerated, { recursive: true, force: true });
    }
  }, 120_000);

  it('every pre-chain entry is attributed to an RC via spec ownership', () => {
    const matrix = readMatrix();
    const preChain = matrix.entries.filter((entry) => entry.preChain === true);
    // Pre-chain paths (introduced by the rejected control package / ChatInput
    // baseline fix) must carry a non-null RC owner.
    for (const entry of preChain) {
      expect(entry.commit).toBeNull();
      expect(entry.rc).toMatch(/^RC-/);
    }
    // Paths first touched by an accepted RC commit carry that commit.
    const commitOwned = matrix.entries.filter((entry) => entry.commit !== null);
    expect(commitOwned.length).toBeGreaterThan(0);
    for (const entry of commitOwned) {
      expect(entry.commit).toMatch(/^[a-f0-9]{40}$/);
    }
  });
});
